                int mergeOffset = SHIFTED_DIAGNOSTIC_MERGE_PAIR_OFFSET * 2 + sample * 2;
                float sourceFinalWeight = samples.get(mergeOffset);
                float mergeWeight = samples.get(mergeOffset + 1);
